"""Evidence report (JSON and Markdown). Deterministic; every number is tagged SYNTHETIC."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any

from .. import __version__
from .._deps import PILOTTRACE_COMMIT
from ..integrations.oes_adapter import channel_table
from ..scenarios import SimConfig

REPORT_SCHEMA_VERSION = 1
BOUNDARIES = (
    "SYNTHETIC data only: route, sensors, faults and labels are generated by this software (seed 42).",
    "No physical sensor or other hardware is involved; the low-drift inertial profile is a hypothetical parameter "
    "set, not a model of any device.",
    "No sensor benefit, calibration or fitness for operational use is established by this replay.",
    "This is a deterministic software replay. It is not a navigation system, an integrity monitor, an alarm, or a "
    "safety function.",
    "Detection numbers describe these invented scenarios and declared scales only; real-data performance is UNRUN.",
)


def build_evidence(
    config: SimConfig, scenarios: Sequence[dict[str, Any]], dropout_comparison: Sequence[dict[str, Any]]
) -> dict[str, Any]:
    return {
        "report_schema_version": REPORT_SCHEMA_VERSION,
        "title": "PilotTrace Navigation Replay Pack: evidence report",
        "evidence_tag": "SYNTHETIC",
        "code_version": __version__,
        "scoring_of_record": f"pilottrace (unmodified, commit {PILOTTRACE_COMMIT[:12]})",
        "boundaries": list(BOUNDARIES),
        "config": config.to_dict(),
        "latch": {
            "score": "S = 0.45*Peak + 0.35*RMS + 0.20*MeanAbs over one 32-value block of x - x_ref (x_ref = 0)",
            "residual": "R = max|x - x_ref|",
            "rule": f"block latches when S >= tau (tau = {config.tau}); a frame latches when any block latches",
            "frame_label": "a frame is labelled degraded when any epoch in its 32-epoch window is degraded",
        },
        "channels": channel_table(),
        "scenarios": list(scenarios),
        "dropout_profile_comparison": list(dropout_comparison),
    }


def _fmt(value: Any) -> str:
    if value is None:
        return "n/a"
    if isinstance(value, float):
        return f"{value:.3f}".rstrip("0").rstrip(".") if abs(value) < 1e6 else f"{value:.3g}"
    return str(value)


def render_markdown(evidence: dict[str, Any]) -> str:
    lines = [
        f"# {evidence['title']}",
        "",
        f"Code version {evidence['code_version']}; scoring of record: {evidence['scoring_of_record']}. "
        f"Seed {evidence['config']['seed']}, {evidence['config']['epochs']} epochs at 1 Hz, "
        f"tau = {evidence['config']['tau']}, inertial profile `{evidence['config']['inertial_profile']}`.",
        "",
        "**Every number in this report is SYNTHETIC.**",
        "",
        "## Boundaries",
        "",
        *[f"- {line}" for line in evidence["boundaries"]],
        "",
        "## Scenario summary (SYNTHETIC)",
        "",
        "| scenario | frames | labelled degraded | latched | false-alarm frames | recall | specificity "
        "| max nav error (m) |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for s in evidence["scenarios"]:
        m = s["pilottrace_descriptive_metrics"]
        lines.append(
            f"| {s['name']} | {s['frames']} | {s['frames_labelled_degraded']} | {s['frames_latched']} "
            f"| {s['false_alarm_frames']} | {_fmt(m['descriptive_recall_sensitivity'])} "
            f"| {_fmt(m['descriptive_specificity'])} | {_fmt(s['nav_error_m']['max'])} |"
        )
    lines += [
        "",
        "## Labelled events (SYNTHETIC)",
        "",
        "Latched channels count frames from event start until 31 epochs after its end (frames whose window "
        "still contains event epochs).",
        "",
        "| scenario | event | epochs | latched during event | latency (s) | latched frames during / after "
        "| latched channels (frames) | expected channel during event | nav error at end (m) |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for s in evidence["scenarios"]:
        for e in s["events"]:
            if not e["within_run"]:
                lines.append(f"| {s['name']} | {e['kind']} | {e['start_epoch']}-{e['end_epoch_exclusive']} | "
                             "outside the run | n/a | n/a | n/a | n/a | n/a |")
                continue
            channels = ", ".join(f"{k} ({v})" for k, v in e["latched_channels"].items()) or "none"
            lines.append(
                f"| {s['name']} | {e['kind']} | {e['start_epoch']}-{e['end_epoch_exclusive']} | "
                f"{'yes' if e['detected_during_event'] else 'NO'} | {_fmt(e['detection_latency_s'])} | "
                f"{e['latched_frames_during_event']} / {e['latched_frames_after_end']} | {channels} | "
                f"{'yes' if e['expected_channel_latched_during_event'] else 'NO'} | "
                f"{_fmt(e['nav_error_at_event_end_m'])} |"
            )
    lines += [
        "",
        "## Dead-reckoning error during the 300 s GNSS dropout, by assumed inertial profile (SYNTHETIC)",
        "",
        "| profile | gyro bias (deg/s) | error at dropout end (m) | max error during dropout (m) |",
        "|---|---|---|---|",
    ]
    for row in evidence["dropout_profile_comparison"]:
        lines.append(
            f"| {row['inertial_profile']} | {row['gyro_bias_dps']} | {_fmt(row['nav_error_at_dropout_end_m'])} "
            f"| {_fmt(row['nav_error_max_during_dropout_m'])} |"
        )
    lines += [
        "",
        "The profiles are parameter assumptions. The difference between rows follows from the assumed gyro bias "
        "and noise; it is not evidence about any real sensor, and no sensor benefit is established.",
        "",
        "## Cross-check",
        "",
        "Every frame was scored by the unmodified pilottrace package and by the fail-closed adapter; "
        + ", ".join(
            f"{s['name']}: {s['cross_check']['latch_disagreements']} latch disagreements, "
            f"max |dS| = {s['cross_check']['max_abs_score_difference']:.1e}"
            for s in evidence["scenarios"]
        )
        + ".",
        "",
        "## Channel map (block b = channel b over the last 32 epochs)",
        "",
        "| block | channel | unit | scale | description |",
        "|---|---|---|---|---|",
        *[
            f"| {c['block']} | {c['name']} | {c['unit']} | {_fmt(c['scale'])} | {c['description']} |"
            for c in evidence["channels"]
        ],
        "",
    ]
    return "\n".join(lines)
